        "titolo_orig": "Maturità, esami col bavaglio",
        "testo_it": "Proteste degli studenti medi in Italia contro la riforma Valditara durante gli esami di maturità.",
        "priorita": "Bassa",
        "id_gruppo": 25,
        "link": "https://ilmanifesto.it/maturita-esami-col-bavaglio",
        "orario": "00:05",
